import { screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../tests/utils";
import { InspectorView } from "../types/inspector";
import { Canvas } from "./Canvas";

vi.mock("reactflow", () => ({
  ReactFlow: () => <div data-testid="react-flow" />,
}));

vi.mock("./BottomControls", () => ({
  BottomControls: () => <div data-testid="bottom-controls" />,
}));

vi.mock("../components/InspectorViewHeader", () => ({
  InspectorViewHeader: ({
    title,
    text,
    showViewSwitcher,
  }: {
    title: string;
    text?: string;
    showViewSwitcher?: boolean;
  }) => (
    <div
      data-testid="inspector-view-header"
      data-title={title}
      data-text={text}
      data-show-view-switcher={String(showViewSwitcher)}
    />
  ),
}));

const mockHandleResize = vi.fn();
const mockHandleInit = vi.fn();
const mockHandleNodesChange = vi.fn();
vi.mock("../CanvasContext", () => ({
  useCanvasContext: () => ({
    flowName: "my_flow",
    nodes: [],
    edges: [],
    handleResize: mockHandleResize,
    handleInit: mockHandleInit,
    handleNodesChange: mockHandleNodesChange,
  }),
}));

const mockIsLargeScreen = vi.fn(() => false);
vi.mock("../hooks/useIsLargeScreen", () => ({
  useIsLargeScreen: () => mockIsLargeScreen(),
}));

describe("Canvas", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockIsLargeScreen.mockReturnValue(false);
  });

  it("renders the ReactFlow, controls, and header", () => {
    renderWithProviders(<Canvas />);
    expect(screen.getByTestId("canvas")).toBeInTheDocument();
    expect(screen.getByTestId("react-flow")).toBeInTheDocument();
    expect(screen.getByTestId("bottom-controls")).toBeInTheDocument();
    expect(screen.getByTestId("inspector-view-header")).toBeInTheDocument();
  });

  it("passes 'Current flow:' as the header title and the flow name as text", () => {
    renderWithProviders(<Canvas />);
    const header = screen.getByTestId("inspector-view-header");
    expect(header.dataset.title).toBe("Current flow: ");
    expect(header.dataset.text).toBe("my_flow");
  });

  it("shows the view switcher when not on a large screen with All view", () => {
    renderWithProviders(<Canvas />, {
      initialStoreState: { inspectorView: InspectorView.All },
    });
    const header = screen.getByTestId("inspector-view-header");
    expect(header.dataset.showViewSwitcher).toBe("true");
  });

  it("hides the view switcher on a large screen with All view", () => {
    mockIsLargeScreen.mockReturnValue(true);
    renderWithProviders(<Canvas />, {
      initialStoreState: { inspectorView: InspectorView.All },
    });
    const header = screen.getByTestId("inspector-view-header");
    expect(header.dataset.showViewSwitcher).toBe("false");
  });
});
